import { useState } from 'react';
import { Alert,StyleSheet,Text,View } from '@/platform/react-native';
import { useLocalSearchParams } from '@/router';
import { CameraView,useCameraPermissions } from '@/platform/camera';
import { api } from '@/lib/api';
import { Button,Card,Muted,Screen,useAppTheme } from '@/components/UI';
export default function ScanCard(){const{id,eventId,meetingId}=useLocalSearchParams<{id:string;eventId?:string;meetingId?:string}>();const{palette}=useAppTheme();const[permission,requestPermission]=useCameraPermissions();const[locked,setLocked]=useState(false);const[result,setResult]=useState<any>(null);async function scanned(data:string){if(locked)return;setLocked(true);try{const r=await api.post(`/communities/${id}/check-in`,{qrPayload:data,eventId:eventId||undefined,meetingId:meetingId||undefined});setResult(r.data.member);Alert.alert('Membership verified',`${r.data.member.FirstName} ${r.data.member.LastName} is an active member${eventId?' and has been checked in to the event':meetingId?' and attendance has been recorded':''}.`);}catch(e:any){Alert.alert('Invalid card',e.response?.data?.error??'Unable to verify this QR code.');setLocked(false)}}return <Screen>{!permission?<View style={s.center}><Muted>Checking camera permission…</Muted></View>:!permission.granted?<Card><Muted>Camera permission is required to scan a CDA Connect membership QR code.</Muted><Button title="Allow Camera" onPress={requestPermission}/></Card>:<><View style={s.camera}><CameraView active facing="back" style={StyleSheet.absoluteFill} barcodeScannerSettings={{barcodeTypes:['qr']}} onBarcodeScanned={locked?undefined:(e:any)=>scanned(e.data)}/><View pointerEvents="none" style={s.frame}/></View><Muted style={s.help}>Point the camera at a CDA Connect membership QR code.</Muted>{result?<Card><Text style={[s.member,{color:palette.text}]}>✓ {result.FirstName} {result.LastName}</Text><Button title="Scan Another" variant="secondary" onPress={()=>{setResult(null);setLocked(false)}}/></Card>:null}</>}</Screen>}
const s=StyleSheet.create({center:{flex:1,alignItems:'center',justifyContent:'center'},camera:{width:'100%',height:500,maxHeight:'72%',borderRadius:22,overflow:'hidden',backgroundColor:'#000',alignItems:'center',justifyContent:'center'},frame:{width:'62%',maxWidth:230,aspectRatio:1,borderWidth:3,borderColor:'#fff',borderRadius:20},help:{textAlign:'center',marginTop:12},member:{fontSize:18,fontWeight:'900',flexShrink:1}})
